"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["767"],{82669(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.processo_seletivo.identificador_legivel_tamanho","status":422,"titulo":"O identificador leg\xedvel deve ter entre 3 e 64 caracteres"},"descricao":{"codigo":"uniplus.selecao.processo_seletivo.identificador_legivel_tamanho","requisitos":[],"oQueAconteceu":["O valor informado como identificador leg\xedvel tem menos de 3 ou mais de 64 caracteres, contados depois de retirados os espa\xe7os das pontas.","O identificador leg\xedvel \xe9 escolhido por quem cadastra o processo e deriva dele o endere\xe7o da p\xe1gina p\xfablica do certame e a chave do documento no acervo. Por isso ele segue um formato fechado: de 3 a 64 caracteres: letras min\xfasculas sem acento, algarismos e h\xedfens, come\xe7ando por letra, terminando em letra ou algarismo e sem h\xedfens consecutivos. Ele n\xe3o pode ter o formato de um identificador gerado pelo sistema."],"comoResolver":["Informe um identificador com 3 a 64 caracteres, por exemplo `medicina-2027`. O processo continua como estava at\xe9 que um valor v\xe1lido seja gravado."],"ondeAparece":["Cria\xe7\xe3o do processo seletivo","Altera\xe7\xe3o do identificador leg\xedvel do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Processo seletivo"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"418da40321f5e48caae8956b248f9336904d661a"}}')}}]);